            logs=[d.json.loads(s) for s in (folder/'training.jsonl').read_text().splitlines()];assert [r['step'] for r in logs]==list(range(1,1001)) and [list(k) for row in logs for k in row['samples']]==[list(k) for k in order];assert all(np.isfinite(r['loss']) and np.isfinite(r['gradient_norm']) for r in logs)
