                assert v['extra'].shape==(1024,1030) and v['position'].shape==(1024,52) and v['alpha'].shape==(1024,) and v['position'][:,46:].count_nonzero()==0
                assert all(v[k].dtype==torch.float32 and torch.isfinite(v[k]).all() for k in ('extra','position','alpha'))
                for arm,kernel in v['kernels'].items():
                    assert arm in d.ARMS and kernel.dtype==torch.float32 and kernel.shape==(1024,1024) and torch.isfinite(kernel).all();assert kernel.mean(-1).abs().max()<2e-6
