    before=d.read(d.OUT/'living_docs_before.json');growth=sum(max(0,(d.ROOT/p).stat().st_size-v['bytes']) for p,v in before.items());project=d.bytes_used(d.OUT)+sum(p.stat().st_size for p in (d.ROOT/'experiments').glob('native_read_address*.py'))+(d.ROOT/'models/native_read_address.py').stat().st_size+growth+10*2**20;assert project<=2**30
