    for row in checks['training_backend_first_batches']:lines.append(f"- seed{row['seed']}：原B首批损失{row['saved_B_fused_evaluation_loss']:.9g}；零gamma MATH训练{row['zero_gamma_math_training_loss']}；相对差%={row['relative_loss_difference_percent']}。")
